    name: { de: "Carmanah Walbran Provincial Park Wald", hu: "Carmanah Walbran Tartományi Park erdő", ro: "Pădurea Parcului Provincial Carmanah Walbran", en: "Carmanah Walbran Provincial Park Forest"},
